from __future__ import annotations

import json
from typing import Any, Dict

import pandas as pd


def monthly_revenue(json_text: str) -> dict:
    """
    Parse `json_text` (a JSON array of objects with keys: "date" (YYYY-MM-DD) and
    "amount" (a number)) and return a dict mapping "YYYY-MM" to the float total
    of amounts for every calendar month from the earliest to the latest month
    present, including months with no records (total 0.0).

    Keys are inserted in chronological order.
    """
    if json_text is None:
        raise TypeError("json_text must be a JSON string, not None")

    # Parse using json module first to ensure we accept "standard" JSON input.
    records: Any = json.loads(json_text)
    if records is None:
        return {}

    if not isinstance(records, list):
        raise ValueError("Expected json_text to be a JSON array of objects")

    # Build a DataFrame; missing keys result in NaN.
    df = pd.DataFrame(records)
    if df.empty:
        return {}

    if "date" not in df.columns or "amount" not in df.columns:
        raise KeyError('Each object must contain keys "date" and "amount"')

    df = df[["date", "amount"]].copy()
    df["date"] = pd.to_datetime(df["date"], errors="raise")
    df["amount"] = pd.to_numeric(df["amount"], errors="raise")

    if df.empty:
        return {}

    month_end = df["date"].dt.to_period("M").dt.to_timestamp("M")
    grouped = df.groupby(month_end, sort=True)["amount"].sum()

    start = month_end.min()
    end = month_end.max()
    full_month_ends = pd.date_range(start=start, end=end, freq="ME")

    monthly = grouped.reindex(full_month_ends, fill_value=0.0)

    result: Dict[str, float] = {}
    for ts, val in monthly.items():
        # ts is a month-end Timestamp; format to YYYY-MM.
        result[ts.strftime("%Y-%m")] = float(val)
    return result
